class Solution:
    def numOfWays(self, n: int) -> int:
        MOD = 10**9 + 7
        grid = [[0] * 3 for _ in range(n)]
        def rec(r, c):
            if r == n:
                return 1
            nr, nc = (r, c + 1) if c < 2 else (r + 1, 0)
            total = 0
            for col in range(1, 4):
                if c > 0 and grid[r][c - 1] == col:
                    continue
                if r > 0 and grid[r - 1][c] == col:
                    continue
                grid[r][c] = col
                total += rec(nr, nc)
            return total % MOD
        return rec(0, 0)

