class Solution {
public:
    int n;
    vector<vector<int>> g;
    const int MOD = 1e9 + 7;
    long long rec(int r, int c) {
        if (r == n) return 1;
        int nr = c < 2 ? r : r + 1, nc = c < 2 ? c + 1 : 0;
        long long total = 0;
        for (int col = 1; col <= 3; col++) {
            if (c > 0 && g[r][c - 1] == col) continue;
            if (r > 0 && g[r - 1][c] == col) continue;
            g[r][c] = col;
            total += rec(nr, nc);
        }
        return total % MOD;
    }
    int numOfWays(int N) {
        n = N;
        g.assign(n, vector<int>(3));
        return rec(0, 0);
    }
};

