    function rec(r, c) {
        if (r === n) return 1;
        const nr = c < 2 ? r : r + 1, nc = c < 2 ? c + 1 : 0;
        let total = 0;
        for (let col = 1; col <= 3; col++) {
            if (c > 0 && g[r][c - 1] === col) continue;
            if (r > 0 && g[r - 1][c] === col) continue;
            g[r][c] = col;
            total += rec(nr, nc);
        }
        return total % MOD;
    }
    return rec(0, 0);
};

